+import { AppError } from "../errors.js";
+import { memoryStore } from "../db/store.js";
+import { t } from "../i18n/messages.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { consume } from "./batches.js";
+
+/** Imports validated sale rows atomically, skipping tickets already recorded. */
+export function importSalesRows(store, rows) {
+  const draft = memoryStore(store.data);
+  const known = new Set(draft.data.sales.map((s) => s.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  for (const row of rows) {
+    try {
+      const dish = getDish(draft, row.dishId);
+      const ingredients = scaled(getRecipe(draft, dish.recipeId), row.qty);
+      if (known.has(row.ticket)) continue;
+      for (const ingredient of ingredients) {
+        if (ingredient.qty > 0)
+          consume(draft, ingredient.itemId, ingredient.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+      }
+      draft.data.sales.push({ id: draft.nextId("sale"), ticket: row.ticket, soldAt: row.soldAt, dishId: row.dishId, qty: row.qty, ingredients });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      throw new AppError("bad_request", { reason: `row ${row.row}: ${t(error.code, "en", error.params)}` });
+    }
+  }
+  store.data = draft.data;
+  return { tickets: tickets.size, dishes };
+}
